      "questions": [
        {"id":"v94-math-equations-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"MODEL","contextFamily":"FIXED_PLUS_RATE","statement":"Um serviço cobra R$ 12 de taxa fixa e R$ 5 por entrega. Qual expressão representa o custo de n entregas?","options":["17n","12 + 5n","12n + 5","5 + 12/n"],"correctAnswer":"12 + 5n","explanation":"A taxa fixa é paga uma vez e o valor variável é R$ 5 multiplicado pelo número n de entregas.","estimatedMinutes":4,"position":0,"metadata":{"content_id":"v94-math-equations-01","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"MATHEMATICS_EQUATION_MODELING_V94","purpose":"PROBE","difficulty":"EASY","cognitive_process":"MODEL","context_family":"FIXED_PLUS_RATE","error_focus":"Definir a variável sem unidade ou significado","remediation_hint":"Antes de marcar, substitua o valor encontrado na relação original e confira unidade, sinal e restrições.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-math-equations-02","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"DEFINE_VARIABLE","statement":"Se x representa a idade atual de Bia, como representar a idade dela daqui a 4 anos?","options":["x + 4","4x","x - 4","4 - x"],"correctAnswer":"x + 4","explanation":"O tempo futuro acrescenta quatro anos à idade atual, portanto a expressão é x + 4.","estimatedMinutes":4,"position":1,"metadata":{"content_id":"v94-math-equations-02","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"MATHEMATICS_EQUATION_MODELING_V94","purpose":"PROBE","difficulty":"EASY","cognitive_process":"IDENTIFY","context_family":"DEFINE_VARIABLE","error_focus":"Definir a variável sem unidade ou significado","remediation_hint":"Antes de marcar, substitua o valor encontrado na relação original e confira unidade, sinal e restrições.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-math-equations-03","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"APPLY","contextFamily":"LINEAR_EQUATION","statement":"Uma empresa compra 3 caixas iguais e paga R$ 25, incluindo R$ 7 de entrega. Qual valor unitário x satisfaz 3x + 7 = 25?","options":["4","8","18","6"],"correctAnswer":"6","explanation":"Subtraindo os R$ 7 de entrega, restam R$ 18 para três caixas. Cada caixa custa R$ 6, e 3 × 6 + 7 = 25 confirma o resultado.","estimatedMinutes":4,"position":0,"metadata":{"content_id":"v94-math-equations-03","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"MATHEMATICS_EQUATION_MODELING_V94","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"APPLY","context_family":"LINEAR_EQUATION","error_focus":"Definir a variável sem unidade ou significado","remediation_hint":"Antes de marcar, substitua o valor encontrado na relação original e confira unidade, sinal e restrições.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-math-equations-04","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"MODEL","contextFamily":"ORDER_WORDS","statement":"“Cinco a menos que o triplo de um número x” corresponde a:","options":["5 - 3x","3(x - 5)","3x - 5","x - 15"],"correctAnswer":"3x - 5","explanation":"Primeiro calcula-se o triplo, 3x; depois retiram-se cinco unidades.","estimatedMinutes":4,"position":1,"metadata":{"content_id":"v94-math-equations-04","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"MATHEMATICS_EQUATION_MODELING_V94","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"MODEL","context_family":"ORDER_WORDS","error_focus":"Definir a variável sem unidade ou significado","remediation_hint":"Antes de marcar, substitua o valor encontrado na relação original e confira unidade, sinal e restrições.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-math-equations-05","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"PARENTHESES","statement":"Qual expressão representa “o dobro da soma de um número x com 6”?","options":["2x + 6","2(x + 6)","x + 12","6x + 2"],"correctAnswer":"2(x + 6)","explanation":"A soma x + 6 acontece primeiro e todo o resultado é multiplicado por 2.","estimatedMinutes":4,"position":2,"metadata":{"content_id":"v94-math-equations-05","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"MATHEMATICS_EQUATION_MODELING_V94","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"COMPARE","context_family":"PARENTHESES","error_focus":"Definir a variável sem unidade ou significado","remediation_hint":"Antes de marcar, substitua o valor encontrado na relação original e confira unidade, sinal e restrições.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-math-equations-06","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"VERIFY","contextFamily":"CONTEXT_CHECK","statement":"A equação 4p + 10 = 34 modela um custo. Qual valor de p satisfaz o modelo?","options":["6","4","8","11"],"correctAnswer":"6","explanation":"4·6 + 10 = 34. As demais opções não reproduzem o custo total.","estimatedMinutes":4,"position":3,"metadata":{"content_id":"v94-math-equations-06","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"MATHEMATICS_EQUATION_MODELING_V94","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"VERIFY","context_family":"CONTEXT_CHECK","error_focus":"Definir a variável sem unidade ou significado","remediation_hint":"Antes de marcar, substitua o valor encontrado na relação original e confira unidade, sinal e restrições.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-math-equations-07","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"MODEL","contextFamily":"INEQUALITY_BUDGET","statement":"Uma atividade custa R$ 8 por pessoa e o grupo dispõe de até R$ 72. Qual condição para o número n de pessoas expressa o limite?","options":["8n ≥ 72","n + 8 = 72","72n ≤ 8","8n ≤ 72"],"correctAnswer":"8n ≤ 72","explanation":"“Até R$ 72” inclui valores menores ou iguais a 72, então o custo variável não pode exceder esse limite.","estimatedMinutes":4,"position":4,"metadata":{"content_id":"v94-math-equations-07","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"MATHEMATICS_EQUATION_MODELING_V94","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"MODEL","context_family":"INEQUALITY_BUDGET","error_focus":"Definir a variável sem unidade ou significado","remediation_hint":"Antes de marcar, substitua o valor encontrado na relação original e confira unidade, sinal e restrições.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-math-equations-08","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"APPLY","contextFamily":"SOLVE_INEQUALITY","statement":"Para 5x - 2 < 18, qual condição resulta?","options":["x > 4","x < 16","x < 4","x > 16"],"correctAnswer":"x < 4","explanation":"Somando 2 e dividindo por 5, positivo, o sentido permanece: x < 4.","estimatedMinutes":4,"position":5,"metadata":{"content_id":"v94-math-equations-08","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"MATHEMATICS_EQUATION_MODELING_V94","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"APPLY","context_family":"SOLVE_INEQUALITY","error_focus":"Definir a variável sem unidade ou significado","remediation_hint":"Antes de marcar, substitua o valor encontrado na relação original e confira unidade, sinal e restrições.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-math-equations-09","purpose":"PRACTICE","difficulty":"HARD","cognitiveProcess":"APPLY","contextFamily":"NEGATIVE_DIVISION","statement":"Resolvendo -3x ≥ 12, qual resultado é correto?","options":["x ≥ -4","x ≤ -4","x ≤ 4","x ≥ 4"],"correctAnswer":"x ≤ -4","explanation":"Dividir por -3 inverte o sinal da inequação, resultando em x ≤ -4.","estimatedMinutes":4,"position":6,"metadata":{"content_id":"v94-math-equations-09","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"MATHEMATICS_EQUATION_MODELING_V94","purpose":"PRACTICE","difficulty":"HARD","cognitive_process":"APPLY","context_family":"NEGATIVE_DIVISION","error_focus":"Definir a variável sem unidade ou significado","remediation_hint":"Antes de marcar, substitua o valor encontrado na relação original e confira unidade, sinal e restrições.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-math-equations-10","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"APPLY","contextFamily":"TWO_STEPS","statement":"Uma expressão para o custo da atividade é 2(x - 3) = 14. Qual valor de x resolve essa igualdade?","options":["10","4","8","17"],"correctAnswer":"10","explanation":"Dividindo os dois lados por 2, obtemos x − 3 = 7. Somar 3 aos dois lados dá x = 10; a substituição mantém a igualdade.","estimatedMinutes":4,"position":7,"metadata":{"content_id":"v94-math-equations-10","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"MATHEMATICS_EQUATION_MODELING_V94","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"APPLY","context_family":"TWO_STEPS","error_focus":"Definir a variável sem unidade ou significado","remediation_hint":"Antes de marcar, substitua o valor encontrado na relação original e confira unidade, sinal e restrições.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-math-equations-11","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"MODEL","contextFamily":"COMPARING_PLANS","statement":"O plano A custa R$ 20 mais R$ 3 por uso; o B custa R$ 8 mais R$ 5 por uso. Para quantos usos os custos são iguais?","options":["12","4","6","28"],"correctAnswer":"6","explanation":"Igualando 20 + 3u a 8 + 5u, temos 12 = 2u, então u = 6.","estimatedMinutes":4,"position":0,"metadata":{"content_id":"v94-math-equations-11","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"MATHEMATICS_EQUATION_MODELING_V94","purpose":"TRANSFER","difficulty":"HARD","cognitive_process":"MODEL","context_family":"COMPARING_PLANS","error_focus":"Definir a variável sem unidade ou significado","remediation_hint":"Antes de marcar, substitua o valor encontrado na relação original e confira unidade, sinal e restrições.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-math-equations-12","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"INTEGER_DOMAIN","statement":"Uma van comporta no máximo 8 estudantes. Se já há 3, qual inequação limita as novas vagas n?","options":["n ≥ 5","n < 8","3n ≤ 8","n ≤ 5"],"correctAnswer":"n ≤ 5","explanation":"O total é 3 + n e deve ser no máximo 8; logo n ≤ 5.","estimatedMinutes":4,"position":1,"metadata":{"content_id":"v94-math-equations-12","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"MATHEMATICS_EQUATION_MODELING_V94","purpose":"TRANSFER","difficulty":"MEDIUM","cognitive_process":"INTERPRET","context_family":"INTEGER_DOMAIN","error_focus":"Definir a variável sem unidade ou significado","remediation_hint":"Antes de marcar, substitua o valor encontrado na relação original e confira unidade, sinal e restrições.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-math-equations-13","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"MODEL","contextFamily":"UNKNOWN_TOTAL","statement":"Uma caixa tinha x peças. Depois de retirar 9, restaram 17. Qual equação modela a situação?","options":["9 - x = 17","x + 17 = 9","x - 9 = 17","9x = 17"],"correctAnswer":"x - 9 = 17","explanation":"Retirar 9 do total inicial deixa 17, por isso x - 9 = 17.","estimatedMinutes":4,"position":2,"metadata":{"content_id":"v94-math-equations-13","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"MATHEMATICS_EQUATION_MODELING_V94","purpose":"TRANSFER","difficulty":"MEDIUM","cognitive_process":"MODEL","context_family":"UNKNOWN_TOTAL","error_focus":"Definir a variável sem unidade ou significado","remediation_hint":"Antes de marcar, substitua o valor encontrado na relação original e confira unidade, sinal e restrições.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-math-equations-14","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"INTERPRET","contextFamily":"SOLUTION_SET","statement":"Para x + 2 ≥ 7, qual conjunto descreve as soluções reais?","options":["Todos os x com x ≥ 5","Somente x = 5","Todos os x com x ≤ 5","Todos os x com x > 7"],"correctAnswer":"Todos os x com x ≥ 5","explanation":"Subtrair 2 preserva o sentido e dá x ≥ 5; a igualdade também é solução.","estimatedMinutes":4,"position":3,"metadata":{"content_id":"v94-math-equations-14","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"MATHEMATICS_EQUATION_MODELING_V94","purpose":"TRANSFER","difficulty":"HARD","cognitive_process":"INTERPRET","context_family":"SOLUTION_SET","error_focus":"Definir a variável sem unidade ou significado","remediation_hint":"Antes de marcar, substitua o valor encontrado na relação original e confira unidade, sinal e restrições.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-math-equations-15","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"UNIT_MODEL","statement":"Uma piscina recebe 15 litros por minuto. Se V é o volume acrescentado após t minutos, qual modelo e unidade são coerentes?","options":["V = 15 + t, com V em minutos.","V = 15t, com V em litros e t em minutos.","t = 15V, com V em litros.","V = t/15, com V em litros por minuto."],"correctAnswer":"V = 15t, com V em litros e t em minutos.","explanation":"A taxa de 15 litros por minuto multiplicada pelo tempo fornece o volume em litros.","estimatedMinutes":4,"position":0,"metadata":{"content_id":"v94-math-equations-15","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"MATHEMATICS_EQUATION_MODELING_V94","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitive_process":"EVALUATE","context_family":"UNIT_MODEL","error_focus":"Definir a variável sem unidade ou significado","remediation_hint":"Antes de marcar, substitua o valor encontrado na relação original e confira unidade, sinal e restrições.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-math-equations-16","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"NO_SOLUTION_CONTEXT","statement":"Um ingresso custa R$ 14 e o orçamento é R$ 50. A desigualdade 14n ≤ 50 admite quantos ingressos inteiros no máximo?","options":["4","2","5","3"],"correctAnswer":"3","explanation":"50 dividido por 14 é aproximadamente 3,57; como n é inteiro, o maior valor possível é 3.","estimatedMinutes":4,"position":1,"metadata":{"content_id":"v94-math-equations-16","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"MATHEMATICS_EQUATION_MODELING_V94","purpose":"LOCK_IN","difficulty":"HARD","cognitive_process":"ANALYZE","context_family":"NO_SOLUTION_CONTEXT","error_focus":"Definir a variável sem unidade ou significado","remediation_hint":"Antes de marcar, substitua o valor encontrado na relação original e confira unidade, sinal e restrições.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-math-equations-17","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"MODEL","contextFamily":"FORMULATE","statement":"Um número somado ao seu dobro resulta em 45. Qual equação representa a frase?","options":["x + 2 = 45","2(x + 45) = 0","x + 2x = 45","45x = 2"],"correctAnswer":"x + 2x = 45","explanation":"O número é x e seu dobro é 2x; a soma dessas parcelas é 45.","estimatedMinutes":4,"position":2,"metadata":{"content_id":"v94-math-equations-17","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"MATHEMATICS_EQUATION_MODELING_V94","purpose":"LOCK_IN","difficulty":"HARD","cognitive_process":"MODEL","context_family":"FORMULATE","error_focus":"Definir a variável sem unidade ou significado","remediation_hint":"Antes de marcar, substitua o valor encontrado na relação original e confira unidade, sinal e restrições.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-math-equations-18","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"VERIFY","contextFamily":"CHECK_ROOT","statement":"Qual valor verifica a equação 7y - 4 = 31?","options":["5","4","6","35"],"correctAnswer":"5","explanation":"Substituindo y = 5, temos 7 × 5 − 4 = 35 − 4 = 31; portanto, esse valor satisfaz a equação.","estimatedMinutes":4,"position":0,"metadata":{"content_id":"v94-math-equations-18","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"MATHEMATICS_EQUATION_MODELING_V94","purpose":"REVIEW","difficulty":"MEDIUM","cognitive_process":"VERIFY","context_family":"CHECK_ROOT","error_focus":"Definir a variável sem unidade ou significado","remediation_hint":"Antes de marcar, substitua o valor encontrado na relação original e confira unidade, sinal e restrições.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-math-equations-19","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"INTERPRET","contextFamily":"INTERVAL","statement":"Uma temperatura deve ficar acima de 18 °C e no máximo em 24 °C. Qual condição representa T?","options":["18 ≤ T < 24","18 < T ≤ 24","T < 18 ou T > 24","18 > T ≥ 24"],"correctAnswer":"18 < T ≤ 24","explanation":"“Acima de 18” exclui 18; “no máximo em 24” inclui 24.","estimatedMinutes":4,"position":1,"metadata":{"content_id":"v94-math-equations-19","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"MATHEMATICS_EQUATION_MODELING_V94","purpose":"REVIEW","difficulty":"HARD","cognitive_process":"INTERPRET","context_family":"INTERVAL","error_focus":"Definir a variável sem unidade ou significado","remediation_hint":"Antes de marcar, substitua o valor encontrado na relação original e confira unidade, sinal e restrições.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-math-equations-20","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"SYNTHESIS","statement":"Ao resolver um problema, uma estudante encontra x = -2 para a quantidade de caixas compradas. O que deve fazer?","options":["Aceitar o resultado porque toda equação tem solução contextual.","Trocar o sinal sem conferir a equação.","Arredondar -2 para zero automaticamente.","Verificar o modelo e o domínio, pois uma quantidade de caixas não pode ser negativa."],"correctAnswer":"Verificar o modelo e o domínio, pois uma quantidade de caixas não pode ser negativa.","explanation":"Uma solução algébrica pode não pertencer ao domínio contextual. É preciso reexaminar a modelagem e as restrições.","estimatedMinutes":4,"position":2,"metadata":{"content_id":"v94-math-equations-20","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"MATHEMATICS_EQUATION_MODELING_V94","purpose":"REVIEW","difficulty":"HARD","cognitive_process":"EVALUATE","context_family":"SYNTHESIS","error_focus":"Definir a variável sem unidade ou significado","remediation_hint":"Antes de marcar, substitua o valor encontrado na relação original e confira unidade, sinal e restrições.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}}
      ]
