        {"id":"v94-english-digital-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"REQUEST_PURPOSE","statement":"Read: “Could you review my paragraph before class?” What is the main purpose?","options":["To ask someone to review a paragraph.","To announce that class is cancelled.","To describe a past holiday.","To sell a writing course."],"correctAnswer":"To ask someone to review a paragraph.","explanation":"The question form and the phrase “review my paragraph” make this a request for feedback.","estimatedMinutes":4,"position":0,"metadata":{"content_id":"v94-english-digital-01","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"ENGLISH_DIGITAL_COMMUNICATION_V94","purpose":"PROBE","difficulty":"EASY","cognitive_process":"IDENTIFY","context_family":"REQUEST_PURPOSE","error_focus":"Choosing a register without considering the audience","remediation_hint":"When answering, point to words or design choices that support your interpretation and avoid inferring facts that the message does not provide.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-english-digital-02","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"INFER","contextFamily":"AUDIENCE","statement":"A message begins “Dear Admissions Team” and includes an application number. Who is the likely audience?","options":["A close friend in a group chat.","A sports audience at a stadium.","An admissions office.","A person selling the applicant a phone."],"correctAnswer":"An admissions office.","explanation":"The formal greeting and application number point to an admissions team, though they do not identify a particular institution.","estimatedMinutes":4,"position":1,"metadata":{"content_id":"v94-english-digital-02","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"ENGLISH_DIGITAL_COMMUNICATION_V94","purpose":"PROBE","difficulty":"EASY","cognitive_process":"INFER","context_family":"AUDIENCE","error_focus":"Choosing a register without considering the audience","remediation_hint":"When answering, point to words or design choices that support your interpretation and avoid inferring facts that the message does not provide.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-english-digital-03","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"DEADLINE","statement":"“Please upload the file by Friday at noon.” When is the requested deadline?","options":["Thursday evening.","Friday at 12:00.","Any time next week.","Only after the meeting."],"correctAnswer":"Friday at 12:00.","explanation":"“By Friday at noon” specifies a latest time of 12:00 on Friday.","estimatedMinutes":4,"position":0,"metadata":{"content_id":"v94-english-digital-03","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"ENGLISH_DIGITAL_COMMUNICATION_V94","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"INTERPRET","context_family":"DEADLINE","error_focus":"Choosing a register without considering the audience","remediation_hint":"When answering, point to words or design choices that support your interpretation and avoid inferring facts that the message does not provide.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-english-digital-04","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"REGISTER","statement":"Which opening is more suitable for a first email to a university office?","options":["Yo, what's up?","Hey bestie!!!","Sup, send me the info.","Dear Student Services Team,"],"correctAnswer":"Dear Student Services Team,","explanation":"The first opening is polite and appropriately formal for an unfamiliar institutional audience.","estimatedMinutes":4,"position":1,"metadata":{"content_id":"v94-english-digital-04","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"ENGLISH_DIGITAL_COMMUNICATION_V94","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"COMPARE","context_family":"REGISTER","error_focus":"Choosing a register without considering the audience","remediation_hint":"When answering, point to words or design choices that support your interpretation and avoid inferring facts that the message does not provide.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-english-digital-05","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"CLARITY","statement":"Which request gives the clearest action and time?","options":["Please send the revised chart by 2 p.m. today.","Send it sometime.","You know what I mean.","The chart is around here."],"correctAnswer":"Please send the revised chart by 2 p.m. today.","explanation":"The request names the action, the object and a specific deadline.","estimatedMinutes":4,"position":2,"metadata":{"content_id":"v94-english-digital-05","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"ENGLISH_DIGITAL_COMMUNICATION_V94","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"EVALUATE","context_family":"CLARITY","error_focus":"Choosing a register without considering the audience","remediation_hint":"When answering, point to words or design choices that support your interpretation and avoid inferring facts that the message does not provide.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-english-digital-06","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"TONE","statement":"A classmate writes “Thanks for catching that typo!” after feedback. What does the message most likely communicate?","options":["A demand to cancel the class.","A verified news report.","Appreciation for the correction.","A refusal to read the feedback."],"correctAnswer":"Appreciation for the correction.","explanation":"“Thanks” and the reference to catching a typo indicate appreciation in this context.","estimatedMinutes":4,"position":3,"metadata":{"content_id":"v94-english-digital-06","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"ENGLISH_DIGITAL_COMMUNICATION_V94","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"ANALYZE","context_family":"TONE","error_focus":"Choosing a register without considering the audience","remediation_hint":"When answering, point to words or design choices that support your interpretation and avoid inferring facts that the message does not provide.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-english-digital-07","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"APPLY","contextFamily":"SUBJECT_LINE","statement":"Which subject line best helps a teacher identify an email about a missed assignment?","options":["Hello","Question about the science assignment due Monday","Important!!!","Read this now"],"correctAnswer":"Question about the science assignment due Monday","explanation":"It identifies the topic and deadline without relying on vague or alarmist wording.","estimatedMinutes":4,"position":4,"metadata":{"content_id":"v94-english-digital-07","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"ENGLISH_DIGITAL_COMMUNICATION_V94","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"APPLY","context_family":"SUBJECT_LINE","error_focus":"Choosing a register without considering the audience","remediation_hint":"When answering, point to words or design choices that support your interpretation and avoid inferring facts that the message does not provide.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-english-digital-08","purpose":"PRACTICE","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"LINK_VERIFICATION","statement":"A forwarded message says “Your account will close in 10 minutes” and includes an unfamiliar link. What is the safest reading strategy?","options":["Open the link immediately because the message is urgent.","Forward it to everyone to ask whether it is real.","Assume it is authentic because it has a logo.","Verify the claim through the service's official channel before opening the link."],"correctAnswer":"Verify the claim through the service's official channel before opening the link.","explanation":"Urgency and visual branding do not establish authenticity; independent verification avoids trusting an unknown link.","estimatedMinutes":4,"position":5,"metadata":{"content_id":"v94-english-digital-08","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"ENGLISH_DIGITAL_COMMUNICATION_V94","purpose":"PRACTICE","difficulty":"HARD","cognitive_process":"EVALUATE","context_family":"LINK_VERIFICATION","error_focus":"Choosing a register without considering the audience","remediation_hint":"When answering, point to words or design choices that support your interpretation and avoid inferring facts that the message does not provide.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-english-digital-09","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"EMOJI_CONTEXT","statement":"A teammate replies “Great job 🙂” after a completed task. What is the most reasonable interpretation?","options":["The words and emoji together suggest positive feedback in this context.","The emoji proves the sender is being sarcastic.","The message contains no meaning because it is short.","The sender has made a formal promise."],"correctAnswer":"The words and emoji together suggest positive feedback in this context.","explanation":"The positive words and a friendly emoji support praise, while an emoji alone would not prove tone in every situation.","estimatedMinutes":4,"position":6,"metadata":{"content_id":"v94-english-digital-09","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"ENGLISH_DIGITAL_COMMUNICATION_V94","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"ANALYZE","context_family":"EMOJI_CONTEXT","error_focus":"Choosing a register without considering the audience","remediation_hint":"When answering, point to words or design choices that support your interpretation and avoid inferring facts that the message does not provide.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-english-digital-10","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"EDIT","contextFamily":"REVISION","statement":"Choose the clearest revision: “Need notes. Send.”","options":["Notes are what meetings have.","Send, maybe, the thing.","I received the notes yesterday.","Could you send me the meeting notes by 4 p.m.?"],"correctAnswer":"Could you send me the meeting notes by 4 p.m.?","explanation":"The revision states the requested action, the specific item and a useful deadline in a polite form.","estimatedMinutes":4,"position":7,"metadata":{"content_id":"v94-english-digital-10","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"ENGLISH_DIGITAL_COMMUNICATION_V94","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"EDIT","context_family":"REVISION","error_focus":"Choosing a register without considering the audience","remediation_hint":"When answering, point to words or design choices that support your interpretation and avoid inferring facts that the message does not provide.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-english-digital-11","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"INTERPRET","contextFamily":"MULTIMODAL","statement":"A poster shows a bus icon beside “Route changes start Monday” and a link labeled “Check your stop.” What does the icon contribute?","options":["It proves every bus will stop running.","It supplies the exact new timetable.","It helps signal that the notice concerns bus travel.","It identifies who designed the poster."],"correctAnswer":"It helps signal that the notice concerns bus travel.","explanation":"The icon supports the topic, while the route details must be checked in the linked information.","estimatedMinutes":4,"position":0,"metadata":{"content_id":"v94-english-digital-11","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"ENGLISH_DIGITAL_COMMUNICATION_V94","purpose":"TRANSFER","difficulty":"HARD","cognitive_process":"INTERPRET","context_family":"MULTIMODAL","error_focus":"Choosing a register without considering the audience","remediation_hint":"When answering, point to words or design choices that support your interpretation and avoid inferring facts that the message does not provide.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-english-digital-12","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"APPLY","contextFamily":"AUDIENCE_ADAPTATION","statement":"You are asking an unfamiliar project partner to share a document. Which message best fits the situation?","options":["Drop it here, stranger.","Hello, could you share the draft when you have a chance? We need it for Thursday's review.","Send the thing.","You have to know what I want."],"correctAnswer":"Hello, could you share the draft when you have a chance? We need it for Thursday's review.","explanation":"The greeting, clear request and relevant deadline fit a professional collaboration without being unnecessarily stiff.","estimatedMinutes":4,"position":1,"metadata":{"content_id":"v94-english-digital-12","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"ENGLISH_DIGITAL_COMMUNICATION_V94","purpose":"TRANSFER","difficulty":"HARD","cognitive_process":"APPLY","context_family":"AUDIENCE_ADAPTATION","error_focus":"Choosing a register without considering the audience","remediation_hint":"When answering, point to words or design choices that support your interpretation and avoid inferring facts that the message does not provide.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-english-digital-13","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"FACT_CHECK","statement":"A post claims that a new school rule begins tomorrow but gives no source. What should a reader do before sharing it?","options":["Share it because the word “new” sounds current.","Change the date and repost it.","Treat comments as official confirmation.","Check an official school channel or contact the school."],"correctAnswer":"Check an official school channel or contact the school.","explanation":"An official channel or direct confirmation provides stronger evidence than an unsupported post or comments.","estimatedMinutes":4,"position":2,"metadata":{"content_id":"v94-english-digital-13","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"ENGLISH_DIGITAL_COMMUNICATION_V94","purpose":"TRANSFER","difficulty":"HARD","cognitive_process":"EVALUATE","context_family":"FACT_CHECK","error_focus":"Choosing a register without considering the audience","remediation_hint":"When answering, point to words or design choices that support your interpretation and avoid inferring facts that the message does not provide.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-english-digital-14","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"APPLY","contextFamily":"POLITE_DISAGREEMENT","statement":"Which reply disagrees while keeping a collaborative tone?","options":["That makes no sense. Stop talking.","I agree with everything, although I do not.","I see your point; could we compare it with the data from the second table?","No data matters."],"correctAnswer":"I see your point; could we compare it with the data from the second table?","explanation":"The reply acknowledges the other view and proposes evidence-based comparison rather than attacking the person.","estimatedMinutes":4,"position":3,"metadata":{"content_id":"v94-english-digital-14","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"ENGLISH_DIGITAL_COMMUNICATION_V94","purpose":"TRANSFER","difficulty":"MEDIUM","cognitive_process":"APPLY","context_family":"POLITE_DISAGREEMENT","error_focus":"Choosing a register without considering the audience","remediation_hint":"When answering, point to words or design choices that support your interpretation and avoid inferring facts that the message does not provide.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
