        {"id":"v94-english-digital-16","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitiveProcess":"INFER","contextFamily":"CONTEXTUAL_MEANING","statement":"In “Please mute your microphone while another person is presenting,” what does “mute” mean?","options":["Turn off the microphone's audio input temporarily.","Delete the presentation.","Leave the online meeting.","Increase the speaker volume."],"correctAnswer":"Turn off the microphone's audio input temporarily.","explanation":"The meeting context and microphone reference show that mute means temporarily disabling audio input.","estimatedMinutes":4,"position":1,"metadata":{"content_id":"v94-english-digital-16","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"ENGLISH_DIGITAL_COMMUNICATION_V94","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitive_process":"INFER","context_family":"CONTEXTUAL_MEANING","error_focus":"Choosing a register without considering the audience","remediation_hint":"When answering, point to words or design choices that support your interpretation and avoid inferring facts that the message does not provide.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-english-digital-17","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"PRIVACY","statement":"A group chat asks everyone to post a photo of a student ID to confirm attendance. What is a responsible response?","options":["Post the ID because all group members are classmates.","Forward someone else's ID instead.","Add the ID number to a public comment.","Avoid posting sensitive identification in the group and ask for a safer official method."],"correctAnswer":"Avoid posting sensitive identification in the group and ask for a safer official method.","explanation":"An ID contains sensitive personal information; attendance should be confirmed through an appropriate private channel.","estimatedMinutes":4,"position":2,"metadata":{"content_id":"v94-english-digital-17","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"ENGLISH_DIGITAL_COMMUNICATION_V94","purpose":"LOCK_IN","difficulty":"HARD","cognitive_process":"EVALUATE","context_family":"PRIVACY","error_focus":"Choosing a register without considering the audience","remediation_hint":"When answering, point to words or design choices that support your interpretation and avoid inferring facts that the message does not provide.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-english-digital-18","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"EDIT","contextFamily":"REVISION_TONE","statement":"Which edit makes “You forgot the file” more constructive while keeping the issue clear?","options":["You always forget everything.","File.","I can't see the file attached. Could you send it when you can?","No one can work with you."],"correctAnswer":"I can't see the file attached. Could you send it when you can?","explanation":"The revised wording describes the observable issue and makes a clear request without generalizing about the person.","estimatedMinutes":4,"position":0,"metadata":{"content_id":"v94-english-digital-18","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"ENGLISH_DIGITAL_COMMUNICATION_V94","purpose":"REVIEW","difficulty":"MEDIUM","cognitive_process":"EDIT","context_family":"REVISION_TONE","error_focus":"Choosing a register without considering the audience","remediation_hint":"When answering, point to words or design choices that support your interpretation and avoid inferring facts that the message does not provide.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-english-digital-19","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"INTENT_LIMIT","statement":"A message says “The meeting may move to room 12; I am waiting for confirmation.” What is known?","options":["The meeting definitely moved to room 12.","A room change is possible but not yet confirmed.","The meeting was cancelled.","The sender has confirmed a new time."],"correctAnswer":"A room change is possible but not yet confirmed.","explanation":"“May” and “waiting for confirmation” mark the change as uncertain, not settled.","estimatedMinutes":4,"position":1,"metadata":{"content_id":"v94-english-digital-19","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"ENGLISH_DIGITAL_COMMUNICATION_V94","purpose":"REVIEW","difficulty":"HARD","cognitive_process":"ANALYZE","context_family":"INTENT_LIMIT","error_focus":"Choosing a register without considering the audience","remediation_hint":"When answering, point to words or design choices that support your interpretation and avoid inferring facts that the message does not provide.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
