      "questions": [
        {"id":"v94-chem-solutions-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"SOLUTE_SOLVENT","statement":"Ao dissolver açúcar em água até formar uma mistura homogênea, qual papel a água desempenha?","options":["Soluto.","Solvente.","Produto gasoso.","Indicador de pH necessariamente."],"correctAnswer":"Solvente.","explanation":"A água é o meio que dissolve o açúcar e, nessa mistura, funciona como solvente.","estimatedMinutes":4,"position":0,"metadata":{"content_id":"v94-chem-solutions-01","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"CHEMISTRY_SOLUTION_CONCENTRATION_V94","purpose":"PROBE","difficulty":"EASY","cognitive_process":"IDENTIFY","context_family":"SOLUTE_SOLVENT","error_focus":"Usar o volume de solvente no lugar do volume final da solução","remediation_hint":"Escreva massa, volume e unidade do resultado antes de substituir os valores na fórmula.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-chem-solutions-02","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"APPLY","contextFamily":"MASS_CONCENTRATION","statement":"Uma solução contém 10 g de soluto em 2 L. Qual é a concentração comum?","options":["5 g/L","20 g/L","0,2 g/L","12 g/L"],"correctAnswer":"5 g/L","explanation":"A concentração comum é a massa dividida pelo volume final: C = 10 g ÷ 2 L = 5 g/L. A unidade indica massa por litro.","estimatedMinutes":4,"position":1,"metadata":{"content_id":"v94-chem-solutions-02","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"CHEMISTRY_SOLUTION_CONCENTRATION_V94","purpose":"PROBE","difficulty":"EASY","cognitive_process":"APPLY","context_family":"MASS_CONCENTRATION","error_focus":"Usar o volume de solvente no lugar do volume final da solução","remediation_hint":"Escreva massa, volume e unidade do resultado antes de substituir os valores na fórmula.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-chem-solutions-03","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"SOLUTION_VOLUME","statement":"Para calcular C = m/V em g/L, que volume deve ser usado?","options":["A massa do solvente em gramas.","O volume do recipiente vazio.","Sempre o volume inicial de água, mesmo após completar a solução.","O volume final da solução, expresso em litros."],"correctAnswer":"O volume final da solução, expresso em litros.","explanation":"A concentração relaciona a massa de soluto ao volume da solução preparada.","estimatedMinutes":4,"position":0,"metadata":{"content_id":"v94-chem-solutions-03","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"CHEMISTRY_SOLUTION_CONCENTRATION_V94","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"INTERPRET","context_family":"SOLUTION_VOLUME","error_focus":"Usar o volume de solvente no lugar do volume final da solução","remediation_hint":"Escreva massa, volume e unidade do resultado antes de substituir os valores na fórmula.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-chem-solutions-04","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"APPLY","contextFamily":"CONVERT_ML","statement":"Há 6 g de soluto em 300 mL de solução. Qual concentração em g/L?","options":["2 g/L","0,02 g/L","20 g/L","1800 g/L"],"correctAnswer":"20 g/L","explanation":"300 mL = 0,300 L; 6/0,300 = 20 g/L.","estimatedMinutes":4,"position":1,"metadata":{"content_id":"v94-chem-solutions-04","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"CHEMISTRY_SOLUTION_CONCENTRATION_V94","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"APPLY","context_family":"CONVERT_ML","error_focus":"Usar o volume de solvente no lugar do volume final da solução","remediation_hint":"Escreva massa, volume e unidade do resultado antes de substituir os valores na fórmula.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-chem-solutions-05","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"PREDICT","contextFamily":"DILUTION_DIRECTION","statement":"Ao adicionar solvente a uma solução sem perder soluto, a concentração tende a:","options":["Aumentar automaticamente.","Diminuir.","Permanecer sempre igual.","Tornar-se igual à massa do recipiente."],"correctAnswer":"Diminuir.","explanation":"A mesma quantidade de soluto fica distribuída em um volume maior, reduzindo a razão m/V.","estimatedMinutes":4,"position":2,"metadata":{"content_id":"v94-chem-solutions-05","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"CHEMISTRY_SOLUTION_CONCENTRATION_V94","purpose":"PRACTICE","difficulty":"EASY","cognitive_process":"PREDICT","context_family":"DILUTION_DIRECTION","error_focus":"Usar o volume de solvente no lugar do volume final da solução","remediation_hint":"Escreva massa, volume e unidade do resultado antes de substituir os valores na fórmula.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-chem-solutions-06","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"EXPLAIN","contextFamily":"DILUTION_MASS","statement":"Em uma diluição ideal, qual grandeza do soluto permanece constante?","options":["A quantidade de soluto na porção transferida.","O volume total da solução.","A concentração.","A massa de solvente, mesmo após adicionar água."],"correctAnswer":"A quantidade de soluto na porção transferida.","explanation":"A diluição acrescenta solvente; sem perdas ou reação, a quantidade de soluto transferida não muda.","estimatedMinutes":4,"position":3,"metadata":{"content_id":"v94-chem-solutions-06","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"CHEMISTRY_SOLUTION_CONCENTRATION_V94","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"EXPLAIN","context_family":"DILUTION_MASS","error_focus":"Usar o volume de solvente no lugar do volume final da solução","remediation_hint":"Escreva massa, volume e unidade do resultado antes de substituir os valores na fórmula.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-chem-solutions-07","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"APPLY","contextFamily":"CALCULATE_MASS","statement":"Que massa de soluto é necessária para preparar 0,5 L a 8 g/L?","options":["16 g","8,5 g","0,0625 g","4 g"],"correctAnswer":"4 g","explanation":"m = C·V = 8 g/L × 0,5 L = 4 g.","estimatedMinutes":4,"position":4,"metadata":{"content_id":"v94-chem-solutions-07","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"CHEMISTRY_SOLUTION_CONCENTRATION_V94","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"APPLY","context_family":"CALCULATE_MASS","error_focus":"Usar o volume de solvente no lugar do volume final da solução","remediation_hint":"Escreva massa, volume e unidade do resultado antes de substituir os valores na fórmula.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-chem-solutions-08","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"COMPARE_SAMPLES","statement":"A amostra A tem 12 g em 3 L; B tem 10 g em 2 L. Qual é mais concentrada?","options":["A, com 4 g/L.","As duas, porque as massas são próximas.","B, com 5 g/L.","Não é possível comparar volumes e massas."],"correctAnswer":"B, com 5 g/L.","explanation":"A tem 12/3 = 4 g/L; B tem 10/2 = 5 g/L, portanto B é mais concentrada.","estimatedMinutes":4,"position":5,"metadata":{"content_id":"v94-chem-solutions-08","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"CHEMISTRY_SOLUTION_CONCENTRATION_V94","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"COMPARE","context_family":"COMPARE_SAMPLES","error_focus":"Usar o volume de solvente no lugar do volume final da solução","remediation_hint":"Escreva massa, volume e unidade do resultado antes de substituir os valores na fórmula.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-chem-solutions-09","purpose":"PRACTICE","difficulty":"HARD","cognitiveProcess":"APPLY","contextFamily":"DILUTION_CALC","statement":"Uma solução de 30 g/L tem 0,20 L transferidos e o volume final passa a 0,60 L. Qual é a nova concentração?","options":["90 g/L","10 g/L","6 g/L","30 g/L"],"correctAnswer":"10 g/L","explanation":"A porção contém 30 × 0,20 = 6 g; dividindo pelo volume final de 0,60 L, obtemos 10 g/L.","estimatedMinutes":4,"position":6,"metadata":{"content_id":"v94-chem-solutions-09","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"CHEMISTRY_SOLUTION_CONCENTRATION_V94","purpose":"PRACTICE","difficulty":"HARD","cognitive_process":"APPLY","context_family":"DILUTION_CALC","error_focus":"Usar o volume de solvente no lugar do volume final da solução","remediation_hint":"Escreva massa, volume e unidade do resultado antes de substituir os valores na fórmula.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-chem-solutions-10","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"SOLUBILITY_LIMIT","statement":"Em certa temperatura, parte do sólido permanece no fundo após agitação prolongada. O que isso pode indicar?","options":["A solução atingiu um limite de solubilidade nessas condições.","Toda a substância virou gás.","A massa do solvente é zero.","A concentração pode ser calculada sem conhecer qualquer volume."],"correctAnswer":"A solução atingiu um limite de solubilidade nessas condições.","explanation":"Sólido não dissolvido pode indicar que se atingiu a solubilidade máxima nas condições dadas, embora seja preciso considerar o sistema.","estimatedMinutes":4,"position":7,"metadata":{"content_id":"v94-chem-solutions-10","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"CHEMISTRY_SOLUTION_CONCENTRATION_V94","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"INTERPRET","context_family":"SOLUBILITY_LIMIT","error_focus":"Usar o volume de solvente no lugar do volume final da solução","remediation_hint":"Escreva massa, volume e unidade do resultado antes de substituir os valores na fórmula.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-chem-solutions-11","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"LABEL_READING","statement":"Um rótulo informa 2 g de substância por 100 mL de solução. Qual é a concentração em g/L?","options":["2 g/L","0,2 g/L","20 g/L","200 g/L"],"correctAnswer":"20 g/L","explanation":"100 mL = 0,1 L; 2/0,1 = 20 g/L.","estimatedMinutes":4,"position":0,"metadata":{"content_id":"v94-chem-solutions-11","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"CHEMISTRY_SOLUTION_CONCENTRATION_V94","purpose":"TRANSFER","difficulty":"MEDIUM","cognitive_process":"INTERPRET","context_family":"LABEL_READING","error_focus":"Usar o volume de solvente no lugar do volume final da solução","remediation_hint":"Escreva massa, volume e unidade do resultado antes de substituir os valores na fórmula.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-chem-solutions-12","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"APPLY","contextFamily":"MASS_FROM_CONC","statement":"Quantos gramas de soluto há em 250 mL de solução a 12 g/L?","options":["48 g","12 g","0,3 g","3 g"],"correctAnswer":"3 g","explanation":"250 mL = 0,250 L; m = C·V = 12 × 0,250 = 3 g.","estimatedMinutes":4,"position":1,"metadata":{"content_id":"v94-chem-solutions-12","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"CHEMISTRY_SOLUTION_CONCENTRATION_V94","purpose":"TRANSFER","difficulty":"MEDIUM","cognitive_process":"APPLY","context_family":"MASS_FROM_CONC","error_focus":"Usar o volume de solvente no lugar do volume final da solução","remediation_hint":"Escreva massa, volume e unidade do resultado antes de substituir os valores na fórmula.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-chem-solutions-13","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"APPLY","contextFamily":"DILUTION_STOCK","statement":"Que volume de uma solução 50 g/L contém 5 g de soluto?","options":["10 L","2,5 L","0,10 L","0,01 L"],"correctAnswer":"0,10 L","explanation":"V = m/C = 5/50 = 0,10 L, equivalente a 100 mL.","estimatedMinutes":4,"position":2,"metadata":{"content_id":"v94-chem-solutions-13","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"CHEMISTRY_SOLUTION_CONCENTRATION_V94","purpose":"TRANSFER","difficulty":"HARD","cognitive_process":"APPLY","context_family":"DILUTION_STOCK","error_focus":"Usar o volume de solvente no lugar do volume final da solução","remediation_hint":"Escreva massa, volume e unidade do resultado antes de substituir os valores na fórmula.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-chem-solutions-14","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"MIXTURE_LIMIT","statement":"Um estudante calcula 20 g/L dividindo 10 g por 0,5 L. Depois acrescenta solvente sem informar o volume final. O que falta para calcular a nova concentração?","options":["O volume final após a diluição.","A cor do recipiente.","O nome de quem preparou a solução.","A temperatura de ebulição do soluto, sempre."],"correctAnswer":"O volume final após a diluição.","explanation":"A massa pode ser mantida, mas a nova concentração requer conhecer o volume final.","estimatedMinutes":4,"position":3,"metadata":{"content_id":"v94-chem-solutions-14","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"CHEMISTRY_SOLUTION_CONCENTRATION_V94","purpose":"TRANSFER","difficulty":"HARD","cognitive_process":"EVALUATE","context_family":"MIXTURE_LIMIT","error_focus":"Usar o volume de solvente no lugar do volume final da solução","remediation_hint":"Escreva massa, volume e unidade do resultado antes de substituir os valores na fórmula.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-chem-solutions-15","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"DISTINGUISH","contextFamily":"MOLARITY_DISTINCTION","statement":"Concentração comum em g/L e concentração em mol/L diferem porque:","options":["Ambas usam sempre a mesma unidade e representam a mesma grandeza.","A primeira relaciona massa e volume; a segunda relaciona quantidade de matéria e volume.","g/L mede temperatura e mol/L mede pressão.","A concentração em mol/L não depende do volume."],"correctAnswer":"A primeira relaciona massa e volume; a segunda relaciona quantidade de matéria e volume.","explanation":"As unidades mostram as grandezas distintas: massa por volume e quantidade de matéria por volume.","estimatedMinutes":4,"position":0,"metadata":{"content_id":"v94-chem-solutions-15","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"CHEMISTRY_SOLUTION_CONCENTRATION_V94","purpose":"LOCK_IN","difficulty":"HARD","cognitive_process":"DISTINGUISH","context_family":"MOLARITY_DISTINCTION","error_focus":"Usar o volume de solvente no lugar do volume final da solução","remediation_hint":"Escreva massa, volume e unidade do resultado antes de substituir os valores na fórmula.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-chem-solutions-16","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitiveProcess":"APPLY","contextFamily":"SOLUTION_PREPARATION","statement":"Para preparar exatamente 500 mL de solução em um balão volumétrico, qual etapa final ajuda a atingir o volume correto?","options":["Adicionar 500 mL de água antes de dissolver, sem verificar o volume final.","Encher acima da marca e retirar qualquer quantidade ao acaso.","Medir apenas a massa do recipiente.","Completar cuidadosamente até a marca de 500 mL após dissolver o soluto."],"correctAnswer":"Completar cuidadosamente até a marca de 500 mL após dissolver o soluto.","explanation":"O volume pedido é o da solução final; completar até a marca controla esse volume.","estimatedMinutes":4,"position":1,"metadata":{"content_id":"v94-chem-solutions-16","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"CHEMISTRY_SOLUTION_CONCENTRATION_V94","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitive_process":"APPLY","context_family":"SOLUTION_PREPARATION","error_focus":"Usar o volume de solvente no lugar do volume final da solução","remediation_hint":"Escreva massa, volume e unidade do resultado antes de substituir os valores na fórmula.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-chem-solutions-17","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"TEMPERATURE_SOLUBILITY","statement":"Uma solução saturada é aquecida e mais soluto passa a dissolver. Qual conclusão é apropriada?","options":["Toda substância fica menos solúvel quando aquecida.","A massa dissolvida é independente das condições.","A solubilidade pode depender da temperatura e das substâncias envolvidas.","A mistura deixou de ser uma solução por ter sido aquecida."],"correctAnswer":"A solubilidade pode depender da temperatura e das substâncias envolvidas.","explanation":"A solubilidade varia conforme substância e temperatura; não existe uma regra única para todos os solutos.","estimatedMinutes":4,"position":2,"metadata":{"content_id":"v94-chem-solutions-17","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"CHEMISTRY_SOLUTION_CONCENTRATION_V94","purpose":"LOCK_IN","difficulty":"HARD","cognitive_process":"ANALYZE","context_family":"TEMPERATURE_SOLUBILITY","error_focus":"Usar o volume de solvente no lugar do volume final da solução","remediation_hint":"Escreva massa, volume e unidade do resultado antes de substituir os valores na fórmula.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-chem-solutions-18","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"VERIFY","contextFamily":"ERROR_CHECK","statement":"Qual cálculo apresenta unidade coerente para 9 g em 0,3 L?","options":["30 g/L","2,7 g/L","0,033 g/L","30 L/g"],"correctAnswer":"30 g/L","explanation":"9 g dividido por 0,3 L resulta em 30 g/L; a unidade é massa por volume.","estimatedMinutes":4,"position":0,"metadata":{"content_id":"v94-chem-solutions-18","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"CHEMISTRY_SOLUTION_CONCENTRATION_V94","purpose":"REVIEW","difficulty":"MEDIUM","cognitive_process":"VERIFY","context_family":"ERROR_CHECK","error_focus":"Usar o volume de solvente no lugar do volume final da solução","remediation_hint":"Escreva massa, volume e unidade do resultado antes de substituir os valores na fórmula.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-chem-solutions-19","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"TRANSFER","contextFamily":"CONTEXT_TRANSFER","statement":"Uma receita pede solução a 4 g/L e serão preparados 750 mL. Que massa é necessária?","options":["0,0053 g","3 g","5,3 g","3000 g"],"correctAnswer":"3 g","explanation":"750 mL = 0,750 L; m = 4 × 0,750 = 3 g.","estimatedMinutes":4,"position":1,"metadata":{"content_id":"v94-chem-solutions-19","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"CHEMISTRY_SOLUTION_CONCENTRATION_V94","purpose":"REVIEW","difficulty":"HARD","cognitive_process":"TRANSFER","context_family":"CONTEXT_TRANSFER","error_focus":"Usar o volume de solvente no lugar do volume final da solução","remediation_hint":"Escreva massa, volume e unidade do resultado antes de substituir os valores na fórmula.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}},
        {"id":"v94-chem-solutions-20","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"SYNTHESIS","statement":"Ao revisar um preparo, a ficha informa massa do soluto e concentração final, mas não o volume. Qual relação permite recuperar o volume?","options":["V = C/m, sem unidade.","V = m + C.","V = m·C em qualquer unidade.","V = m/C, mantendo unidades compatíveis."],"correctAnswer":"V = m/C, mantendo unidades compatíveis.","explanation":"De C = m/V, isolamos V = m/C; as unidades devem resultar em volume.","estimatedMinutes":4,"position":2,"metadata":{"content_id":"v94-chem-solutions-20","content_version":"tec-escola-core-v9.4-fourth-journey-expansion-v1","primary_skill":"CHEMISTRY_SOLUTION_CONCENTRATION_V94","purpose":"REVIEW","difficulty":"HARD","cognitive_process":"EVALUATE","context_family":"SYNTHESIS","error_focus":"Usar o volume de solvente no lugar do volume final da solução","remediation_hint":"Escreva massa, volume e unidade do resultado antes de substituir os valores na fórmula.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","mapping_status":"MAPPING_PENDING","demo_preview_only":true}}
