$v94_payload$::jsonb; v_catalog_id uuid; v_subject_id uuid; v_parent_id uuid; v_skill_id uuid; v_lesson_id uuid; v_journey_id uuid; v_set_id uuid; v_question_id uuid; v_count integer; v_purpose_count integer; v_expected_count integer; v_purpose text; v_journey jsonb; v_lesson jsonb; v_question jsonb;
begin
  if to_regclass('supabase_migrations.schema_migrations') is null then raise exception 'V94_MIGRATION_LEDGER_MISSING'; end if;
  if not exists(select 1 from supabase_migrations.schema_migrations where version='20261011000500') or not exists(select 1 from supabase_migrations.schema_migrations where version='20261011000600') then raise exception 'V94_REQUIRES_MIGRATIONS_00500_AND_00600'; end if;
  if exists(select 1 from supabase_migrations.schema_migrations where version='20261011000700') then raise exception 'V94_MIGRATION_ALREADY_RECORDED'; end if;
  select id into v_catalog_id from public.learning_curriculum_catalogs where code='TECESCOLA_CORE' and version='1.0' and active limit 1;
  if v_catalog_id is null then raise exception 'TECESCOLA_CORE_CATALOG_MISSING'; end if;
  for v_journey in select value from jsonb_array_elements(v_payload->'journeys') loop
    select id into v_subject_id from public.learning_canonical_subjects where code=v_journey->>'subject' and active;
    if v_subject_id is null then raise exception 'V94_CANONICAL_SUBJECT_MISSING:%',v_journey->>'subject'; end if;
    select id into v_parent_id from public.learning_curriculum_skills where catalog_id=v_catalog_id and code=v_journey->>'parent' and active and node_kind='ANCHOR';
    if v_parent_id is null then raise exception 'V94_PARENT_ANCHOR_MISSING:%',v_journey->>'parent'; end if;
    insert into public.learning_curriculum_skills(catalog_id,code,stage,grade_level,subject_area,domain,title,description,active,node_kind,content_readiness,mastery_targetable,pedagogical_review_status,bncc_alignment_status,publication_status,canonical_subject_id,parent_canonical_skill_id,metadata) values(v_catalog_id,v_journey->>'skill','ENSINO_MEDIO',1,v_journey->>'subject',v_journey->>'domain',v_journey->>'skillTitle',v_journey->>'skillDescription',true,'LEAF','ADAPTIVE_READY',true,'PEDAGOGICAL_REVIEW_PENDING','CANDIDATE','STAGING',v_subject_id,v_parent_id,v_journey->'skillMetadata') on conflict(catalog_id,code) do nothing returning id into v_skill_id;
    if v_skill_id is null then select id into v_skill_id from public.learning_curriculum_skills where catalog_id=v_catalog_id and code=v_journey->>'skill' and stage='ENSINO_MEDIO' and grade_level=1 and subject_area=v_journey->>'subject' and domain=v_journey->>'domain' and node_kind='LEAF' and content_readiness='ADAPTIVE_READY' and mastery_targetable and pedagogical_review_status='PEDAGOGICAL_REVIEW_PENDING' and bncc_alignment_status='CANDIDATE' and publication_status='STAGING' and canonical_subject_id=v_subject_id and parent_canonical_skill_id=v_parent_id and metadata->>'content_version'=v_payload->>'contentVersion' and metadata->>'demo_preview_only'='true'; end if;
    if v_skill_id is null then raise exception 'V94_SKILL_IDEMPOTENCY_MISMATCH:%',v_journey->>'skill'; end if;
    insert into public.learning_skill_hierarchy(parent_skill_id,child_skill_id) values(v_parent_id,v_skill_id) on conflict(parent_skill_id,child_skill_id) do nothing;
    v_lesson := v_journey->'lesson';
    insert into public.learning_skill_lessons(canonical_skill_id,version,title,summary,content_markdown,worked_example,tips,estimated_minutes,metadata,active) values(v_skill_id,4,v_lesson->>'title',v_lesson->>'summary',v_lesson->>'contentMarkdown',v_lesson->>'workedExample',array(select jsonb_array_elements_text(v_lesson->'tips')),(v_lesson->>'estimatedMinutes')::integer,v_lesson->'metadata',true) on conflict(canonical_skill_id,version) do nothing returning id into v_lesson_id;
    if v_lesson_id is null then select id into v_lesson_id from public.learning_skill_lessons where canonical_skill_id=v_skill_id and version=4 and active and title=v_lesson->>'title' and summary=v_lesson->>'summary' and content_markdown=v_lesson->>'contentMarkdown' and worked_example=v_lesson->>'workedExample' and tips=array(select jsonb_array_elements_text(v_lesson->'tips')) and estimated_minutes=(v_lesson->>'estimatedMinutes')::integer and metadata->>'content_version'=v_payload->>'contentVersion' and metadata->>'demo_preview_only'='true'; end if;
    if v_lesson_id is null then raise exception 'V94_LESSON_IDEMPOTENCY_MISMATCH:%',v_journey->>'skill'; end if;
    for v_purpose in select jsonb_array_elements_text(v_payload->'purposes') loop
      insert into public.learning_question_sets(scope,canonical_skill_id,purpose,version,metadata) values('GLOBAL',v_skill_id,v_purpose,4,jsonb_build_object('content_pack','tec-escola-core-v4','content_version',v_payload->>'contentVersion','selection_policy','SERVER_SELECTED_V1','demo_preview_only',true,'pedagogical_review_status','PEDAGOGICAL_REVIEW_PENDING','mapping_status','MAPPING_PENDING')) on conflict(canonical_skill_id,purpose,version) where scope='GLOBAL' do nothing;
      if not exists(select 1 from public.learning_question_sets where scope='GLOBAL' and canonical_skill_id=v_skill_id and purpose=v_purpose and version=4 and active and metadata->>'content_version'=v_payload->>'contentVersion' and metadata->>'demo_preview_only'='true' and metadata->>'pedagogical_review_status'='PEDAGOGICAL_REVIEW_PENDING') then raise exception 'V94_QUESTION_SET_IDEMPOTENCY_MISMATCH:%:%',v_journey->>'skill',v_purpose; end if;
    end loop;
    insert into public.learning_bncc_discipline_journeys(journey_code,canonical_subject_id,execution_skill_id,unit_code,unit_title,title,suggested_stage,suggested_grade,publication_status,mapping_status,pedagogical_review_status,content_version,metadata) values(v_journey->>'journeyCode',v_subject_id,v_skill_id,v_journey->>'unitCode',v_journey->>'unitTitle',v_journey->>'title','ENSINO_MEDIO',1,'DEMO_PREVIEW','MAPPING_PENDING','PEDAGOGICAL_REVIEW_PENDING',v_payload->>'contentVersion',jsonb_build_object('source_pack',v_payload->>'contentVersion','skill_code',v_journey->>'skill','parent_anchor',v_journey->>'parent','learning_role','INTRODUCTORY_CONTENT','mapping_status','MAPPING_PENDING','pedagogical_review_status','PEDAGOGICAL_REVIEW_PENDING','demonstration_only',true)) on conflict(journey_code) do nothing returning id into v_journey_id;
    if v_journey_id is null then select id into v_journey_id from public.learning_bncc_discipline_journeys where journey_code=v_journey->>'journeyCode' and canonical_subject_id=v_subject_id and execution_skill_id=v_skill_id and unit_code=v_journey->>'unitCode' and title=v_journey->>'title' and suggested_stage='ENSINO_MEDIO' and suggested_grade=1 and publication_status='DEMO_PREVIEW' and mapping_status='MAPPING_PENDING' and pedagogical_review_status='PEDAGOGICAL_REVIEW_PENDING' and content_version=v_payload->>'contentVersion' and active; end if;
    if v_journey_id is null then raise exception 'V94_JOURNEY_IDEMPOTENCY_MISMATCH:%',v_journey->>'skill'; end if;
    for v_question in select value from jsonb_array_elements(v_journey->'questions') loop
      insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active) select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9.4 fourth journey expansion',v_journey->>'subject',v_journey->>'domain',v_question->>'contextFamily',v_question->>'statement',v_question->'options',v_question->'correctAnswer',v_question->>'explanation',v_question->>'difficulty',(v_question->>'estimatedMinutes')::integer,'TECESCOLA_V9_AUTHORIAL_V1',v_question->'metadata',true where not exists(select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'=v_question->>'id') returning id into v_question_id;
      if v_question_id is null then select id into v_question_id from public.learning_question_bank where source_type='TECESCOLA_V9_AUTHORED_V1' and source_name='TecEscola V9.4 fourth journey expansion' and subject_area=v_journey->>'subject' and domain=v_journey->>'domain' and topic=v_question->>'contextFamily' and statement=v_question->>'statement' and options=v_question->'options' and correct_answer=v_question->'correctAnswer' and explanation=v_question->>'explanation' and difficulty=v_question->>'difficulty' and estimated_minutes=(v_question->>'estimatedMinutes')::integer and provenance='TECESCOLA_V9_AUTHORIAL_V1' and metadata=v_question->'metadata' and metadata->>'content_id'=v_question->>'id' and active; end if;
      if v_question_id is null then raise exception 'V94_QUESTION_IDEMPOTENCY_MISMATCH:%',v_question->>'id'; end if;
      insert into public.learning_question_bank_skill_links(question_bank_id,canonical_skill_id,skill_role) values(v_question_id,v_skill_id,'PRIMARY') on conflict(question_bank_id,canonical_skill_id) do nothing;
      if not exists(select 1 from public.learning_question_bank_skill_links where question_bank_id=v_question_id and canonical_skill_id=v_skill_id and skill_role='PRIMARY') then raise exception 'V94_QUESTION_SKILL_LINK_MISSING:%',v_question->>'id'; end if;
      select id into v_set_id from public.learning_question_sets where scope='GLOBAL' and canonical_skill_id=v_skill_id and purpose=v_question->>'purpose' and version=4 and active;
      insert into public.learning_question_set_items(question_set_id,question_bank_id,position) values(v_set_id,v_question_id,(v_question->>'position')::integer) on conflict(question_set_id,question_bank_id) do nothing;
    end loop;
    select count(distinct item.question_bank_id)::integer into v_count from public.learning_question_sets set_row join public.learning_question_set_items item on item.question_set_id=set_row.id join public.learning_question_bank bank on bank.id=item.question_bank_id and bank.active where set_row.scope='GLOBAL' and set_row.canonical_skill_id=v_skill_id and set_row.version=4 and set_row.active and bank.metadata->>'content_version'=v_payload->>'contentVersion';
    if v_count<>20 then raise exception 'V94_QUESTION_POOL_INCOMPLETE:%',v_journey->>'skill'; end if;
    for v_purpose in select jsonb_array_elements_text(v_payload->'purposes') loop
      select (v_payload->'purposeCounts'->>v_purpose)::integer into v_expected_count;
      select count(distinct item.question_bank_id)::integer into v_purpose_count from public.learning_question_sets set_row join public.learning_question_set_items item on item.question_set_id=set_row.id join public.learning_question_bank bank on bank.id=item.question_bank_id and bank.active where set_row.scope='GLOBAL' and set_row.canonical_skill_id=v_skill_id and set_row.version=4 and set_row.active and set_row.purpose=v_purpose and bank.metadata->>'content_version'=v_payload->>'contentVersion';
      if v_purpose_count<>v_expected_count then raise exception 'V94_PURPOSE_POOL_INCOMPLETE:%:%',v_journey->>'skill',v_purpose; end if;
    end loop;
    if not exists(select 1 from public.learning_bncc_discipline_journeys where id=v_journey_id and publication_status='DEMO_PREVIEW' and mapping_status='MAPPING_PENDING' and pedagogical_review_status='PEDAGOGICAL_REVIEW_PENDING') then raise exception 'V94_REVIEW_STATE_INVALID:%',v_journey->>'skill'; end if;
  end loop;
  notify pgrst, 'reload schema';
end $v94_fourth_journeys$;
commit;
